import java.util.Iterator;
import java.util.List;
import java.util.Spliterator;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;

class LmdbTimedOutQueryReadHandleLogCaptureTest {

	@Test
	void streamIterationKeepsItsSnapshotWhileAnotherThreadLogs() throws Exception {
		ListAppender<ILoggingEvent> appender = LmdbTimedOutQueryReadHandleTest.createLogAppender();
		Logger logger = createLogger(appender);
		try {
			logger.info("first");
			logger.info("second");

			List<String> observed = new ArrayList<>();
			try (Stream<ILoggingEvent> events = appender.list.stream()) {
				Spliterator<ILoggingEvent> iterator = events.spliterator();
				assertThat(iterator.tryAdvance(event -> observed.add(event.getFormattedMessage()))).isTrue();

				appendFromWorker(logger);

				iterator.forEachRemaining(event -> observed.add(event.getFormattedMessage()));
			}

			assertThat(observed).containsExactly("first", "second");
			assertThat(messages(appender)).containsExactly("first", "second", "third");
		} finally {
			logger.detachAppender(appender);
			appender.stop();
		}
	}

	@Test
	void iteratorKeepsItsSnapshotWhileAnotherThreadLogs() throws Exception {
		ListAppender<ILoggingEvent> appender = LmdbTimedOutQueryReadHandleTest.createLogAppender();
		Logger logger = createLogger(appender);
		try {
			logger.info("first");
			logger.info("second");

			Iterator<ILoggingEvent> iterator = appender.list.iterator();
			assertThat(iterator.next().getFormattedMessage()).isEqualTo("first");

			appendFromWorker(logger);

			assertThat(iterator.next().getFormattedMessage()).isEqualTo("second");
			assertThat(iterator.hasNext()).isFalse();
			assertThat(messages(appender)).containsExactly("first", "second", "third");
		} finally {
			logger.detachAppender(appender);
			appender.stop();
		}
	}

	private static Logger createLogger(ListAppender<ILoggingEvent> appender) {
		Logger logger = (Logger) LoggerFactory.getLogger(
				LmdbTimedOutQueryReadHandleLogCaptureTest.class.getName() + "." + UUID.randomUUID());
		logger.setLevel(Level.INFO);
		logger.setAdditive(false);
		logger.addAppender(appender);
		return logger;
	}

	private static void appendFromWorker(Logger logger) throws Exception {
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			Future<?> append = executor.submit(() -> logger.info("third"));
			append.get();
		} finally {
			executor.shutdownNow();
		}
	}

	private static List<String> messages(ListAppender<ILoggingEvent> appender) {
		return appender.list.stream().map(ILoggingEvent::getFormattedMessage).toList();
	}
}
